private static boolean isSimpleName(String name) {
        for (int i = 0; i < name.length(); i++) {
            char c = name.charAt(i);
            if (c != '-' && c != '+' && c != '.' && c != '_' && !('0' <= c && c <= '9') &&
                    !('a' <= c && c <= 'z')) {
                return false;
            }
        }
        return name.length() > 0;
    }

